<?php if ($error): ?><div class="admin-error" role="alert"><?= escape($error) ?></div><?php endif; ?><section class="admin-section filter-section"><form method="get" class="filter-form"><label>Date<input type="date" name="date" value="<?= escape($filters['date'] ?? '') ?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach (['pending','confirmed','completed','cancelled','no_show'] as $status): ?><option value="<?= $status ?>" <?= ($filters['status'] ?? '')===$status?'selected':'' ?>><?= ucfirst(str_replace('_',' ',$status)) ?></option><?php endforeach; ?></select></label><label>Therapist<select name="staff_id"><option value="">All therapists</option><?php foreach ($staff as $person): ?><option value="<?= $person['id'] ?>" <?= (string)($filters['staff_id'] ?? '')===(string)$person['id']?'selected':'' ?>><?= escape($person['name']) ?></option><?php endforeach; ?></select></label><label class="filter-search">Search<input name="search" value="<?= escape($filters['search'] ?? '') ?>" placeholder="Reference, client, or phone"></label><button class="admin-button" type="submit">Apply filters</button><a class="clear-filter" href="bookings.php">Clear</a></form></section>
<section class="admin-section"><div class="section-title"><div><p class="admin-eyebrow">BOOKINGS & CALENDAR</p><h2><?= count($bookings) ?> appointments</h2></div><a class="admin-button" href="manual-booking.php">+ New booking</a></div><?php if (!$bookings): ?><div class="admin-empty"><h3>No appointments found.</h3><p>Try clearing the filters or choosing another date.</p></div><?php else: ?><div class="booking-admin-list"><?php foreach ($bookings as $booking): $time=(new DateTimeImmutable($booking['slot_start'],new DateTimeZone('UTC')))->setTimezone(business_timezone()); ?><article class="admin-booking"><div class="booking-date"><span><?= $time->format('D') ?></span><strong><?= $time->format('j M') ?></strong><small><?= $time->format('g:i A') ?></small></div><div class="booking-person"><h3><?= escape($booking['customer_name']) ?></h3><a href="tel:<?= escape($booking['customer_phone']) ?>"><?= escape($booking['customer_phone']) ?></a><small><?= escape($booking['reference']) ?></small></div><div class="booking-service"><strong><?= escape($booking['service_name']) ?></strong><span><?= escape($booking['staff_name']) ?> · <?= $booking['duration_min'] ?> min</span><b><?= money($booking['price']) ?> · <?= $booking['payment_status']==='paid'?'Paid':'Unpaid' ?></b></div><div class="booking-controls"><span class="status status-<?= escape($booking['status']) ?>"><?= escape(str_replace('_',' ',$booking['status'])) ?></span><?php if (in_array($booking['status'],['pending','confirmed'],true)): ?><form method="post"><input type="hidden" name="csrf" value="<?= escape(Csrf::token()) ?>"><input type="hidden" name="booking_id" value="<?= $booking['id'] ?>"><input type="hidden" name="action" value="status"><select name="status" aria-label="Change appointment status"><option value="">Change status…</option><?php if ($booking['status']==='pending'): ?><option value="confirmed">Confirm</option><?php else: ?><option value="completed">Complete</option><option value="no_show">No-show</option><?php endif; ?><option value="cancelled">Cancel</option></select><button type="submit">Apply</button></form><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= escape(Csrf::token()) ?>"><input type="hidden" name="booking_id" value="<?= $booking['id'] ?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="payment_status" value="<?= $booking['payment_status']==='paid'?'unpaid':'paid' ?>"><button type="submit">Mark <?= $booking['payment_status']==='paid'?'unpaid':'paid' ?></button></form></div><?php if ($booking['notes']): ?><p class="booking-notes"><strong>Client note:</strong> <?= escape($booking['notes']) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section>
